patches.new:
case "$1" in
      https://github.com/pyenv/pyenv.git) archive="$OFFLINE_ROOT/resources/pyenv-source.tar.gz" ;;
      https://github.com/pyenv/pyenv-doctor.git) archive="$OFFLINE_ROOT/resources/pyenv-doctor-source.tar.gz" ;;
      https://github.com/pyenv/pyenv-update.git) archive="$OFFLINE_ROOT/resources/pyenv-update-source.tar.gz" ;;
      https://github.com/pyenv/pyenv-virtualenv.git) archive="$OFFLINE_ROOT/resources/pyenv-virtualenv-source.tar.gz" ;;
      *) failed_checkout "$1" ;;
    esac
    mkdir -p "$2"
    tar -xzf "$archive" --strip-components=1 -C "$2" || failed_checkout "$1"
